import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const QuanLyBaoTri = () => {
    const now = new Date();
    const [selectedDate, setSelectedDate] = useState(now.getDate());
    const [selectedMonth, setSelectedMonth] = useState(now.getMonth() + 1);
    const [selectedYear, setSelectedYear] = useState(now.getFullYear());

    const [loading, setLoading] = useState(false);
    const [requests, setRequests] = useState([]);

    useEffect(() => {
        fetchData();
    }, [selectedDate, selectedMonth, selectedYear]);

    const fetchData = () => {
        setLoading(true);
        const allData = JSON.parse(localStorage.getItem('maintenance_db') || '[]');
        const filtered = allData.filter(item => 
            item.day === selectedDate && 
            item.month === selectedMonth && 
            item.year === selectedYear
        );
        setRequests(filtered);
        setLoading(false);
    };

    const updateStatus = (id, newStatus) => {
        const allData = JSON.parse(localStorage.getItem('maintenance_db') || '[]');
        const updated = allData.map(req => req.id === id ? { ...req, status: newStatus } : req);
        localStorage.setItem('maintenance_db', JSON.stringify(updated));
        fetchData(); // Reload bảng
    };

    const getStatusStyle = (status) => {
        if (status === 'pending') return { bg: '#f8d7da', color: '#dc3545' };
        if (status === 'processing') return { bg: '#fff3cd', color: '#856404' };
        return { bg: '#d4edda', color: '#155724' };
    };

    return (
        <div style={adminContainer}>
            <div style={adminHeader}>
                <h2 style={{ color: '#fff', margin: 0 }}>🛠 HỆ THỐNG QUẢN LÝ BẢO TRÌ</h2>
                <div style={{ display: 'flex', gap: '10px' }}>
                    <select value={selectedDate} onChange={(e) => setSelectedDate(Number(e.target.value))} style={selectStyle}>{Array.from({length:31},(_,i)=><option key={i+1} value={i+1}>Ngày {i+1}</option>)}</select>
                    <select value={selectedMonth} onChange={(e) => setSelectedMonth(Number(e.target.value))} style={selectStyle}>{Array.from({length:12},(_,i)=><option key={i+1} value={i+1}>Tháng {i+1}</option>)}</select>
                </div>
            </div>

            <div style={tableWrapper}>
                {loading ? <div style={msg}>Đang tải...</div> : requests.length > 0 ? (
                    <table style={tableStyle}>
                        <thead>
                            <tr style={theadStyle}>
                                <th style={thStyle}>PHÒNG</th>
                                <th style={thStyle}>TIÊU ĐỀ & MÔ TẢ</th>
                                <th style={thStyle}>GIỜ</th>
                                <th style={thStyle}>TRẠNG THÁI</th>
                            </tr>
                        </thead>
                        <tbody>
                            {requests.map(req => (
                                <tr key={req.id} style={trStyle}>
                                    <td style={{ ...tdStyle, fontWeight: 'bold', fontSize: '18px' }}>{req.room}</td>
                                    <td style={tdStyle}>
                                        <div style={{ fontWeight: 'bold' }}>{req.title}</div>
                                        <div style={{ fontSize: '13px', color: '#666' }}>{req.issue}</div>
                                    </td>
                                    <td style={tdStyle}>{req.time}</td>
                                    <td style={tdStyle}>
                                        <select 
                                            value={req.status} 
                                            onChange={(e) => updateStatus(req.id, e.target.value)}
                                            style={{ ...statusSelect, ...getStatusStyle(req.status) }}
                                        >
                                            <option value="pending">Chờ xử lý</option>
                                            <option value="processing">Đang sửa</option>
                                            <option value="completed">Hoàn thành</option>
                                        </select>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                ) : <div style={msg}>Không có yêu cầu nào.</div>}
            </div>
        </div>
    );
};

// Styles Admin
const adminContainer = { flex: 1, display: 'flex', flexDirection: 'column', backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', borderRadius: '30px', height: 'calc(100vh - 120px)', overflow: 'hidden' };
const adminHeader = { padding: '20px 30px', background: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' };
const tableWrapper = { flex: 1, margin: '20px', background: '#fff', borderRadius: '20px', overflowY: 'auto', padding: '10px' };
const tableStyle = { width: '100%', borderCollapse: 'collapse' };
const theadStyle = { background: '#f8f9fa', textAlign: 'left' };
const thStyle = { padding: '15px', color: '#666', borderBottom: '2px solid #eee' };
const trStyle = { borderBottom: '1px solid #eee' };
const tdStyle = { padding: '15px', verticalAlign: 'top' };
const selectStyle = { padding: '8px', borderRadius: '10px', border: 'none', fontWeight: 'bold' };
const statusSelect = { padding: '8px', borderRadius: '8px', border: 'none', fontWeight: 'bold', cursor: 'pointer' };
const msg = { textAlign: 'center', padding: '50px', color: '#999', fontSize: '18px' };

export default QuanLyBaoTri;
